package cbmpc

/*
#include <stdlib.h>
#include "shim.h"
*/
import "C"

import (
	"context"
)

// SignKey is one party's share of a signing key: derived from a Keyset (ECDSA, Ed25519) or generated by DKGBIP340.
type SignKey struct {
	*Secret
	alg  Alg
	role Role
}

func (k *SignKey) Alg() Alg   { return k.alg }
func (k *SignKey) Role() Role { return k.role }

// LoadSignKey wraps a key blob after checking that it parses and is for role. blob is wiped.
func LoadSignKey(alg Alg, role Role, blob []byte) (*SignKey, error) {
	const op = "sign.load"
	if err := checkRole(op, role); err != nil {
		WipeBytes(blob)
		return nil, err
	}
	if len(blob) == 0 || len(blob) > maxBlob {
		WipeBytes(blob)
		return nil, badArg(op, "blob size %d out of range", len(blob))
	}
	var p *C.uint8_t
	var n C.size_t
	err := local(op, func() C.int { return C.qv_2p_pub(C.int(alg), bptr(blob), C.size_t(len(blob)), &p, &n) })
	if err != nil {
		WipeBytes(blob)
		return nil, err
	}
	takeBytes(p, n)
	return &SignKey{SecretFromBytes(blob), alg, role}, nil
}

// PublicKey returns the compressed public key (33 bytes for ECDSA, 32 for Ed25519). For BIP340 it is the 33-byte
// compressed point; use XOnlyPublicKey for the taproot key.
func (k *SignKey) PublicKey() ([]byte, error) {
	const op = "sign.pub"
	var p *C.uint8_t
	var n C.size_t
	err := k.use(func(kp *C.uint8_t, kn C.size_t) error {
		return local(op, func() C.int { return C.qv_2p_pub(C.int(k.alg), kp, kn, &p, &n) })
	})
	if err != nil {
		return nil, wrapWiped(op, err)
	}
	return takeBytes(p, n), nil
}

// XOnlyPublicKey returns the 32-byte x-only key of a BIP340 key.
func (k *SignKey) XOnlyPublicKey() ([]byte, error) {
	const op = "sign.xonly"
	if k.alg != BIP340 {
		return nil, badArg(op, "not a BIP340 key")
	}
	var p *C.uint8_t
	var n C.size_t
	err := k.use(func(kp *C.uint8_t, kn C.size_t) error {
		return local(op, func() C.int { return C.qv_schnorr_xonly(kp, kn, &p, &n) })
	})
	if err != nil {
		return nil, wrapWiped(op, err)
	}
	return takeBytes(p, n), nil
}

// Sign runs the 2-party signing protocol; both parties must call it with the same msg.
//
//   - ECDSA: msg is the 32-byte digest. The result is a DER signature, low-S, verified by cb-mpc against the public
//     key before it is returned. Only the public cb-mpc sign() is used: never the internal global-abort variant.
//   - Ed25519: msg is the full message. Signatures are randomized: store the first one and rebroadcast it.
//   - BIP340: msg is the 32-byte hash; result is a 64-byte BIP340 signature.
//
// Only P1 receives the signature; P2 gets (nil, nil) on success.
func (k *SignKey) Sign(ctx context.Context, tr Transport, msg []byte, opts ...Option) ([]byte, error) {
	op := k.alg.String() + ".sign"
	switch k.alg {
	case ECDSA, BIP340:
		if len(msg) != 32 {
			return nil, badArg(op, "message must be a 32-byte digest, got %d bytes", len(msg))
		}
	default:
		if len(msg) == 0 || len(msg) > maxBlob {
			return nil, badArg(op, "message size %d out of range", len(msg))
		}
	}
	var p *C.uint8_t
	var n C.size_t
	err := k.use(func(kp *C.uint8_t, kn C.size_t) error {
		return run(ctx, tr, op, opts, func(h C.uintptr_t) C.int {
			return C.qv_2p_sign(C.int(k.alg), C.int(k.role), h, kp, kn, bptr(msg), C.size_t(len(msg)), &p, &n)
		})
	})
	if err != nil {
		return nil, wrapWiped(op, err)
	}
	if k.role != P1 {
		return nil, nil
	}
	return takeBytes(p, n), nil
}

// DKGBIP340 generates a non-HD BIP340 (taproot) key with the peer.
func DKGBIP340(ctx context.Context, tr Transport, role Role, opts ...Option) (*SignKey, error) {
	const op = "bip340.dkg"
	if err := checkRole(op, role); err != nil {
		return nil, err
	}
	var p *C.uint8_t
	var n C.size_t
	if err := run(ctx, tr, op, opts, func(h C.uintptr_t) C.int {
		return C.qv_2p_dkg(C.int(BIP340), C.int(role), h, C.QV_CURVE_SECP256K1, &p, &n)
	}); err != nil {
		return nil, err
	}
	return &SignKey{takeSecret(p, n), BIP340, role}, nil
}

// Refresh re-randomizes a BIP340 key's shares together with the peer (same caveats as Keyset.Refresh).
func (k *SignKey) Refresh(ctx context.Context, tr Transport, opts ...Option) (*SignKey, error) {
	const op = "bip340.refresh"
	if k.alg != BIP340 {
		return nil, badArg(op, "only BIP340 keys can be refreshed directly; refresh the Keyset and derive again")
	}
	var p *C.uint8_t
	var n C.size_t
	err := k.use(func(kp *C.uint8_t, kn C.size_t) error {
		return run(ctx, tr, op, opts, func(h C.uintptr_t) C.int {
			return C.qv_2p_refresh(C.int(k.alg), C.int(k.role), h, kp, kn, &p, &n)
		})
	})
	if err != nil {
		return nil, wrapWiped(op, err)
	}
	return &SignKey{takeSecret(p, n), k.alg, k.role}, nil
}
